// Procesar resultado de conversión TikZ
const output = $input.first().json.stdout;
let resultado;

try {
  resultado = JSON.parse(output);
} catch (e) {
  resultado = {
    tikz_code: 'Error en conversión',
    status: 'error',
    error: output
  };
}

// Generar nombre de archivo único
const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const filename = `tikz_generated_${timestamp}.tex`;

return {
  json: {
    tikz_code: resultado.tikz_code,
    filename: filename,
    description: resultado.description,
    status: resultado.status,
    timestamp: resultado.timestamp,
    complexity: resultado.complexity,
    ready_for_use: resultado.status === 'success'
  }
};

// Log de error en conversión
const data = $input.first().json;

console.log('❌ ERROR EN CONVERSIÓN TIKZ:');
console.log(`Descripción: ${data.description}`);
console.log(`Error: ${data.error || 'Conversión fallida'}`);
console.log(`Timestamp: ${data.timestamp}`);

return {
  json: {
    mensaje: '❌ Error en conversión TikZ',
    descripcion: data.description,
    error: data.error || 'Conversión fallida',
    timestamp: data.timestamp,
    requiere_revision: true
  }
};

